/**
 * Worker entry: the OpenNext-built Next.js app, plus the daily jobs that
 * vercel.json used to schedule. Cloudflare fires `scheduled` per cron in
 * wrangler.jsonc; each one calls its route through the app itself (a
 * Worker can't fetch its own URL), authorised with CRON_SECRET exactly as
 * Vercel's cron requests were.
 */
// @ts-expect-error generated by `opennextjs-cloudflare build`
import { default as handler } from './.open-next/worker.js';

const JOBS: Record<string, string> = {
  '0 19 * * *': '/api/sync/availability',
  '15 19 * * *': '/api/signals',
  '30 19 * * *': '/api/enrich',
  '0 20 * * *': '/api/social/draft',
  '0 21 * * *': '/api/social/insights',
};

interface Env {
  NEXT_PUBLIC_APP_URL?: string;
  CRON_SECRET?: string;
}

export default {
  fetch: handler.fetch,

  async scheduled(event: { cron: string }, env: Env, ctx: { waitUntil(p: Promise<unknown>): void }) {
    const path = JOBS[event.cron];
    if (!path) return;
    const base = env.NEXT_PUBLIC_APP_URL || 'https://decra.workers.dev';
    const req = new Request(new URL(path, base), {
      headers: { authorization: `Bearer ${env.CRON_SECRET ?? ''}` },
    });
    const res: Response = await handler.fetch(req, env, ctx);
    console.log(`cron ${event.cron} ${path} -> ${res.status}`);
  },
};
